55	AddressResolver::AddressResolver(Instance &aInstance)
56	    : InstanceLocator(aInstance)
57	    , mAddressError(OT_URI_PATH_ADDRESS_ERROR, &AddressResolver::HandleAddressError, this)
58	    , mAddressQuery(OT_URI_PATH_ADDRESS_QUERY, &AddressResolver::HandleAddressQuery, this)
59	    , mAddressNotification(OT_URI_PATH_ADDRESS_NOTIFY, &AddressResolver::HandleAddressNotification, this)
60	    , mIcmpHandler(&AddressResolver::HandleIcmpReceive, this)
61	    , mTimer(aInstance, &AddressResolver::HandleTimer, this)
62	{
63	    Clear();
64	
65	    Get<Coap::Coap>().AddResource(mAddressError);
66	    Get<Coap::Coap>().AddResource(mAddressQuery);
67	    Get<Coap::Coap>().AddResource(mAddressNotification);
68	
69	    Get<Ip6::Icmp>().RegisterHandler(mIcmpHandler);
70	}
