72	void AddressResolver::Clear(void)
73	{
74	    memset(&mCache, 0, sizeof(mCache));
75	
76	    for (uint8_t i = 0; i < kCacheEntries; i++)
77	    {
78	        mCache[i].mAge = i;
79	    }
80	}
81	
82	otError AddressResolver::GetEntry(uint8_t aIndex, otEidCacheEntry &aEntry) const
83	{
84	    otError error = OT_ERROR_NONE;
85	
86	    VerifyOrExit(aIndex < kCacheEntries, error = OT_ERROR_INVALID_ARGS);
87	    memcpy(&aEntry.mTarget, &mCache[aIndex].mTarget, sizeof(aEntry.mTarget));
88	    aEntry.mRloc16 = mCache[aIndex].mRloc16;
89	    aEntry.mAge    = mCache[aIndex].mAge;
90	    aEntry.mValid  = mCache[aIndex].mState == Cache::kStateCached;
91	
92	exit:
93	    return error;
94	}
