96	void AddressResolver::Remove(uint8_t aRouterId)
97	{
98	    for (int i = 0; i < kCacheEntries; i++)
99	    {
100	        if (Mle::Mle::GetRouterId(mCache[i].mRloc16) == aRouterId)
101	        {
102	            InvalidateCacheEntry(mCache[i], kReasonRemovingRouterId);
103	        }
104	    }
105	}
106	
107	void AddressResolver::Remove(uint16_t aRloc16)
108	{
109	    for (int i = 0; i < kCacheEntries; i++)
110	    {
111	        if (mCache[i].mRloc16 == aRloc16)
112	        {
113	            InvalidateCacheEntry(mCache[i], kReasonRemovingRloc16);
114	        }
115	    }
116	}
117	
118	AddressResolver::Cache *AddressResolver::NewCacheEntry(void)
119	{
120	    Cache *rval = NULL;
121	
122	    for (int i = 0; i < kCacheEntries; i++)
123	    {
124	        if (mCache[i].mState == Cache::kStateQuery && mCache[i].mFailures == 0)
125	        {
126	            continue;
127	        }
128	
129	        if (rval == NULL || rval->mAge < mCache[i].mAge)
130	        {
131	            rval = &mCache[i];
132	        }
133	    }
134	
135	    if (rval != NULL)
136	    {
137	        InvalidateCacheEntry(*rval, kReasonEvictingForNewEntry);
138	    }
139	
140	    return rval;
141	}
142	
143	void AddressResolver::MarkCacheEntryAsUsed(Cache &aEntry)
144	{
145	    for (int i = 0; i < kCacheEntries; i++)
146	    {
147	        if (mCache[i].mAge < aEntry.mAge)
148	        {
149	            mCache[i].mAge++;
150	        }
151	    }
152	
153	    aEntry.mAge = 0;
154	}
