156	const char *AddressResolver::ConvertInvalidationReasonToString(InvalidationReason aReason)
157	{
158	    const char *str = "";
159	
160	    switch (aReason)
161	    {
162	    case kReasonRemovingRouterId:
163	        str = "removing router id";
164	        break;
165	
166	    case kReasonRemovingRloc16:
167	        str = "removing rloc16";
168	        break;
169	
170	    case kReasonReceivedIcmpDstUnreachNoRoute:
171	        str = "received icmp no route";
172	        break;
173	
174	    case kReasonEvictingForNewEntry:
175	        str = "evicting for new entry";
176	        break;
177	    }
178	
179	    return str;
180	}
181	
182	void AddressResolver::InvalidateCacheEntry(Cache &aEntry, InvalidationReason aReason)
183	{
184	    OT_UNUSED_VARIABLE(aReason);
185	
186	    for (int i = 0; i < kCacheEntries; i++)
187	    {
188	        if (mCache[i].mAge > aEntry.mAge)
189	        {
190	            mCache[i].mAge--;
191	        }
192	    }
193	
194	    switch (aEntry.mState)
195	    {
196	    case Cache::kStateCached:
197	        otLogNoteArp("Cache entry removed: %s, 0x%04x - %s", aEntry.mTarget.ToString().AsCString(), aEntry.mRloc16,
198	                     ConvertInvalidationReasonToString(aReason));
199	        break;
200	
201	    case Cache::kStateQuery:
202	        otLogNoteArp("Cache entry (query mode) removed: %s, timeout:%d, retry:%d - %s",
203	                     aEntry.mTarget.ToString().AsCString(), aEntry.mTimeout, aEntry.mRetryTimeout,
204	                     ConvertInvalidationReasonToString(aReason));
205	        break;
206	
207	    default:
208	        break;
209	    }
210	
211	    aEntry.mAge   = kCacheEntries - 1;
212	    aEntry.mState = Cache::kStateInvalid;
213	}
