215	void AddressResolver::UpdateCacheEntry(const Ip6::Address &aEid, Mac::ShortAddress aRloc16)
216	{
217	    for (int i = 0; i < kCacheEntries; i++)
218	    {
219	        if (mCache[i].mState == Cache::kStateInvalid || mCache[i].mTarget != aEid)
220	        {
221	            continue;
222	        }
223	
224	        if (mCache[i].mRloc16 != aRloc16)
225	        {
226	            // not updating the age here is intentional because this cache entry is not actually being used
227	            mCache[i].mRloc16 = aRloc16;
228	
229	            if (mCache[i].mState != Cache::kStateCached)
230	            {
231	                mCache[i].mRetryTimeout        = 0;
232	                mCache[i].mLastTransactionTime = static_cast<uint32_t>(kLastTransactionTimeInvalid);
233	                mCache[i].mTimeout             = 0;
234	                mCache[i].mFailures            = 0;
235	                mCache[i].mState               = Cache::kStateCached;
236	
237	                Get<MeshForwarder>().HandleResolved(aEid, OT_ERROR_NONE);
238	            }
239	
240	            otLogNoteArp("Cache entry updated (snoop): %s, 0x%04x", aEid.ToString().AsCString(), aRloc16);
241	        }
242	
243	        ExitNow();
244	    }
245	
246	exit:
247	    return;
248	}
