250	otError AddressResolver::Resolve(const Ip6::Address &aEid, uint16_t &aRloc16)
251	{
252	    otError error = OT_ERROR_NONE;
253	    Cache * entry = NULL;
254	
255	    for (int i = 0; i < kCacheEntries; i++)
256	    {
257	        if (mCache[i].mState != Cache::kStateInvalid)
258	        {
259	            if (mCache[i].mTarget == aEid)
260	            {
261	                entry = &mCache[i];
262	                break;
263	            }
264	        }
265	    }
266	
267	    if (entry == NULL)
268	    {
269	        entry = NewCacheEntry();
270	    }
271	
272	    VerifyOrExit(entry != NULL, error = OT_ERROR_NO_BUFS);
273	
274	    switch (entry->mState)
275	    {
276	    case Cache::kStateInvalid:
277	        SuccessOrExit(error = SendAddressQuery(aEid));
278	        entry->mTarget       = aEid;
279	        entry->mRloc16       = Mac::kShortAddrInvalid;
280	        entry->mTimeout      = kAddressQueryTimeout;
281	        entry->mFailures     = 0;
282	        entry->mRetryTimeout = kAddressQueryInitialRetryDelay;
283	        entry->mState        = Cache::kStateQuery;
284	        error                = OT_ERROR_ADDRESS_QUERY;
285	        break;
286	
287	    case Cache::kStateQuery:
288	        if (entry->mTimeout > 0)
289	        {
290	            error = OT_ERROR_ADDRESS_QUERY;
291	        }
292	        else if (entry->mTimeout == 0 && entry->mRetryTimeout == 0)
293	        {
294	            SuccessOrExit(error = SendAddressQuery(aEid));
295	            entry->mTimeout = kAddressQueryTimeout;
296	            error           = OT_ERROR_ADDRESS_QUERY;
297	        }
298	        else
299	        {
300	            error = OT_ERROR_DROP;
301	        }
302	
303	        break;
304	
305	    case Cache::kStateCached:
306	        aRloc16 = entry->mRloc16;
307	        MarkCacheEntryAsUsed(*entry);
308	        break;
309	    }
310	
311	exit:
312	    return error;
313	}
