315	otError AddressResolver::SendAddressQuery(const Ip6::Address &aEid)
316	{
317	    otError          error;
318	    Coap::Message *  message;
319	    ThreadTargetTlv  targetTlv;
320	    Ip6::MessageInfo messageInfo;
321	
322	    VerifyOrExit((message = Get<Coap::Coap>().NewMessage()) != NULL, error = OT_ERROR_NO_BUFS);
323	
324	    message->Init(OT_COAP_TYPE_NON_CONFIRMABLE, OT_COAP_CODE_POST);
325	    SuccessOrExit(error = message->AppendUriPathOptions(OT_URI_PATH_ADDRESS_QUERY));
326	    SuccessOrExit(error = message->SetPayloadMarker());
327	
328	    targetTlv.Init();
329	    targetTlv.SetTarget(aEid);
330	    SuccessOrExit(error = message->AppendTlv(targetTlv));
331	
332	    messageInfo.GetPeerAddr().mFields.m16[0] = HostSwap16(0xff03);
333	    messageInfo.GetPeerAddr().mFields.m16[7] = HostSwap16(0x0002);
334	    messageInfo.SetSockAddr(Get<Mle::MleRouter>().GetMeshLocal16());
335	    messageInfo.SetPeerPort(kCoapUdpPort);
336	    messageInfo.SetInterfaceId(Get<ThreadNetif>().GetInterfaceId());
337	
338	    SuccessOrExit(error = Get<Coap::Coap>().SendMessage(*message, messageInfo));
339	
340	    otLogInfoArp("Sending address query for %s", aEid.ToString().AsCString());
341	
342	exit:
343	
344	    if (mTimer.IsRunning() == false)
345	    {
346	        mTimer.Start(kStateUpdatePeriod);
347	    }
348	
349	    if (error != OT_ERROR_NONE && message != NULL)
350	    {
351	        message->Free();
352	    }
353	
354	    return error;
355	}
