362	
363	void AddressResolver::HandleAddressNotification(Coap::Message &aMessage, const Ip6::MessageInfo &aMessageInfo)
364	{
365	    ThreadTargetTlv              targetTlv;
366	    ThreadMeshLocalEidTlv        mlIidTlv;
367	    ThreadRloc16Tlv              rloc16Tlv;
368	    ThreadLastTransactionTimeTlv lastTransactionTimeTlv;
369	    uint32_t                     lastTransactionTime;
370	
371	    VerifyOrExit(aMessage.GetType() == OT_COAP_TYPE_CONFIRMABLE && aMessage.GetCode() == OT_COAP_CODE_POST);
372	
373	    SuccessOrExit(ThreadTlv::GetTlv(aMessage, ThreadTlv::kTarget, sizeof(targetTlv), targetTlv));
374	    VerifyOrExit(targetTlv.IsValid());
375	
376	    SuccessOrExit(ThreadTlv::GetTlv(aMessage, ThreadTlv::kMeshLocalEid, sizeof(mlIidTlv), mlIidTlv));
377	    VerifyOrExit(mlIidTlv.IsValid());
378	
379	    SuccessOrExit(ThreadTlv::GetTlv(aMessage, ThreadTlv::kRloc16, sizeof(rloc16Tlv), rloc16Tlv));
380	    VerifyOrExit(rloc16Tlv.IsValid());
381	
382	    lastTransactionTime = 0;
383	
384	    if (ThreadTlv::GetTlv(aMessage, ThreadTlv::kLastTransactionTime, sizeof(lastTransactionTimeTlv),
385	                          lastTransactionTimeTlv) == OT_ERROR_NONE)
386	    {
387	        VerifyOrExit(lastTransactionTimeTlv.IsValid());
388	        lastTransactionTime = lastTransactionTimeTlv.GetTime();
389	    }
390	
391	    otLogInfoArp("Received address notification from 0x%04x for %s to 0x%04x",
392	                 HostSwap16(aMessageInfo.GetPeerAddr().mFields.m16[7]), targetTlv.GetTarget().ToString().AsCString(),
393	                 rloc16Tlv.GetRloc16());
394	
395	    for (int i = 0; i < kCacheEntries; i++)
396	    {
397	        if (mCache[i].mTarget != targetTlv.GetTarget())
398	        {
399	            continue;
400	        }
401	
402	        switch (mCache[i].mState)
403	        {
404	        case Cache::kStateInvalid:
405	            break;
406	
407	        case Cache::kStateCached:
408	            if (mCache[i].mLastTransactionTime != kLastTransactionTimeInvalid)
409	            {
410	                if (memcmp(mCache[i].mMeshLocalIid, mlIidTlv.GetIid(), sizeof(mCache[i].mMeshLocalIid)) != 0)
411	                {
412	                    SendAddressError(targetTlv, mlIidTlv, NULL);
413	                    ExitNow();
414	                }
415	
416	                if (lastTransactionTime >= mCache[i].mLastTransactionTime)
417	                {
418	                    ExitNow();
419	                }
420	            }
421	
422	            // fall through
423	
424	        case Cache::kStateQuery:
425	            memcpy(mCache[i].mMeshLocalIid, mlIidTlv.GetIid(), sizeof(mCache[i].mMeshLocalIid));
426	            mCache[i].mRloc16              = rloc16Tlv.GetRloc16();
427	            mCache[i].mRetryTimeout        = 0;
428	            mCache[i].mLastTransactionTime = lastTransactionTime;
429	            mCache[i].mTimeout             = 0;
430	            mCache[i].mFailures            = 0;
431	            mCache[i].mState               = Cache::kStateCached;
432	            MarkCacheEntryAsUsed(mCache[i]);
433	
434	            otLogNoteArp("Cache entry updated (notification): %s, 0x%04x, lastTrans:%d",
435	                         targetTlv.GetTarget().ToString().AsCString(), rloc16Tlv.GetRloc16(), lastTransactionTime);
436	
437	            if (Get<Coap::Coap>().SendEmptyAck(aMessage, aMessageInfo) == OT_ERROR_NONE)
438	            {
439	                otLogInfoArp("Sending address notification acknowledgment");
440	            }
441	
442	            Get<MeshForwarder>().HandleResolved(targetTlv.GetTarget(), OT_ERROR_NONE);
443	            break;
444	        }
445	    }
446	
447	exit:
448	    return;
449	}
