451	otError AddressResolver::SendAddressError(const ThreadTargetTlv &      aTarget,
452	                                          const ThreadMeshLocalEidTlv &aEid,
453	                                          const Ip6::Address *         aDestination)
454	{
455	    otError          error;
456	    Coap::Message *  message;
457	    Ip6::MessageInfo messageInfo;
458	
459	    VerifyOrExit((message = Get<Coap::Coap>().NewMessage()) != NULL, error = OT_ERROR_NO_BUFS);
460	
461	    message->Init(aDestination == NULL ? OT_COAP_TYPE_NON_CONFIRMABLE : OT_COAP_TYPE_CONFIRMABLE, OT_COAP_CODE_POST);
462	    SuccessOrExit(error = message->AppendUriPathOptions(OT_URI_PATH_ADDRESS_ERROR));
463	    SuccessOrExit(error = message->SetPayloadMarker());
464	
465	    SuccessOrExit(error = message->AppendTlv(aTarget));
466	    SuccessOrExit(error = message->AppendTlv(aEid));
467	
468	    if (aDestination == NULL)
469	    {
470	        messageInfo.GetPeerAddr().mFields.m16[0] = HostSwap16(0xff03);
471	        messageInfo.GetPeerAddr().mFields.m16[7] = HostSwap16(0x0002);
472	    }
473	    else
474	    {
475	        memcpy(&messageInfo.GetPeerAddr(), aDestination, sizeof(messageInfo.GetPeerAddr()));
476	    }
477	
478	    messageInfo.SetSockAddr(Get<Mle::MleRouter>().GetMeshLocal16());
479	    messageInfo.SetPeerPort(kCoapUdpPort);
480	    messageInfo.SetInterfaceId(Get<ThreadNetif>().GetInterfaceId());
481	
482	    SuccessOrExit(error = Get<Coap::Coap>().SendMessage(*message, messageInfo));
483	
484	    otLogInfoArp("Sending address error for target %s", aTarget.GetTarget().ToString().AsCString());
485	
486	exit:
487	
488	    if (error != OT_ERROR_NONE && message != NULL)
489	    {
490	        message->Free();
491	    }
492	
493	    return error;
494	}
