502	void AddressResolver::HandleAddressError(Coap::Message &aMessage, const Ip6::MessageInfo &aMessageInfo)
503	{
504	    otError               error = OT_ERROR_NONE;
505	    ThreadTargetTlv       targetTlv;
506	    ThreadMeshLocalEidTlv mlIidTlv;
507	    Mac::ExtAddress       macAddr;
508	    Ip6::Address          destination;
509	
510	    VerifyOrExit(aMessage.GetType() == OT_COAP_TYPE_CONFIRMABLE && aMessage.GetCode() == OT_COAP_CODE_POST,
511	                 error = OT_ERROR_DROP);
512	
513	    otLogInfoArp("Received address error notification");
514	
515	    if (aMessage.IsConfirmable() && !aMessageInfo.GetSockAddr().IsMulticast())
516	    {
517	        if (Get<Coap::Coap>().SendEmptyAck(aMessage, aMessageInfo) == OT_ERROR_NONE)
518	        {
519	            otLogInfoArp("Sent address error notification acknowledgment");
520	        }
521	    }
522	
523	    SuccessOrExit(error = ThreadTlv::GetTlv(aMessage, ThreadTlv::kTarget, sizeof(targetTlv), targetTlv));
524	    VerifyOrExit(targetTlv.IsValid(), error = OT_ERROR_PARSE);
525	
526	    SuccessOrExit(error = ThreadTlv::GetTlv(aMessage, ThreadTlv::kMeshLocalEid, sizeof(mlIidTlv), mlIidTlv));
527	    VerifyOrExit(mlIidTlv.IsValid(), error = OT_ERROR_PARSE);
528	
529	    for (const Ip6::NetifUnicastAddress *address = Get<ThreadNetif>().GetUnicastAddresses(); address;
530	         address                                 = address->GetNext())
531	    {
532	        if (address->GetAddress() == targetTlv.GetTarget() &&
533	            memcmp(Get<Mle::MleRouter>().GetMeshLocal64().GetIid(), mlIidTlv.GetIid(), 8))
534	        {
535	            // Target EID matches address and Mesh Local EID differs
536	            Get<ThreadNetif>().RemoveUnicastAddress(*address);
537	            ExitNow();
538	        }
539	    }
540	
541	    memcpy(&macAddr, mlIidTlv.GetIid(), sizeof(macAddr));
542	    macAddr.m8[0] ^= 0x2;
543	
544	    for (ChildTable::Iterator iter(GetInstance(), ChildTable::kInStateValid); !iter.IsDone(); iter++)
545	    {
546	        Child &child = *iter.GetChild();
547	
548	        if (child.IsFullThreadDevice())
549	        {
550	            continue;
551	        }
552	
553	        if (child.GetExtAddress() != macAddr)
554	        {
555	            // Mesh Local EID differs, so check whether Target EID
556	            // matches a child address and if so remove it.
557	
558	            if (child.RemoveIp6Address(GetInstance(), targetTlv.GetTarget()) == OT_ERROR_NONE)
559	            {
560	                memset(&destination, 0, sizeof(destination));
561	                destination.mFields.m16[0] = HostSwap16(0xfe80);
562	                destination.SetIid(child.GetExtAddress());
563	
564	                SendAddressError(targetTlv, mlIidTlv, &destination);
565	                ExitNow();
566	            }
567	        }
568	    }
569	
570	exit:
571	
572	    if (error != OT_ERROR_NONE)
573	    {
574	        otLogWarnArp("Error while processing address error notification: %s", otThreadErrorToString(error));
575	    }
576	}
