583	
584	void AddressResolver::HandleAddressQuery(Coap::Message &aMessage, const Ip6::MessageInfo &aMessageInfo)
585	{
586	    ThreadTargetTlv              targetTlv;
587	    ThreadMeshLocalEidTlv        mlIidTlv;
588	    ThreadLastTransactionTimeTlv lastTransactionTimeTlv;
589	
590	    VerifyOrExit(aMessage.GetType() == OT_COAP_TYPE_NON_CONFIRMABLE && aMessage.GetCode() == OT_COAP_CODE_POST);
591	
592	    SuccessOrExit(ThreadTlv::GetTlv(aMessage, ThreadTlv::kTarget, sizeof(targetTlv), targetTlv));
593	    VerifyOrExit(targetTlv.IsValid());
594	
595	    mlIidTlv.Init();
596	
597	    lastTransactionTimeTlv.Init();
598	
599	    otLogInfoArp("Received address query from 0x%04x for target %s",
600	                 HostSwap16(aMessageInfo.GetPeerAddr().mFields.m16[7]), targetTlv.GetTarget().ToString().AsCString());
601	
602	    if (Get<ThreadNetif>().IsUnicastAddress(targetTlv.GetTarget()))
603	    {
604	        mlIidTlv.SetIid(Get<Mle::MleRouter>().GetMeshLocal64().GetIid());
605	        SendAddressQueryResponse(targetTlv, mlIidTlv, NULL, aMessageInfo.GetPeerAddr());
606	        ExitNow();
607	    }
608	
609	    for (ChildTable::Iterator iter(GetInstance(), ChildTable::kInStateValid); !iter.IsDone(); iter++)
610	    {
611	        Child &child = *iter.GetChild();
612	
613	        if (child.IsFullThreadDevice() || child.GetLinkFailures() >= Mle::kFailedChildTransmissions)
614	        {
615	            continue;
616	        }
617	
618	        if (child.HasIp6Address(GetInstance(), targetTlv.GetTarget()))
619	        {
620	            mlIidTlv.SetIid(child.GetExtAddress());
621	            lastTransactionTimeTlv.SetTime(TimerMilli::Elapsed(child.GetLastHeard()));
622	            SendAddressQueryResponse(targetTlv, mlIidTlv, &lastTransactionTimeTlv, aMessageInfo.GetPeerAddr());
623	            ExitNow();
624	        }
625	    }
626	
627	exit:
628	    return;
629	}
630	
631	void AddressResolver::SendAddressQueryResponse(const ThreadTargetTlv &             aTargetTlv,
632	                                               const ThreadMeshLocalEidTlv &       aMlEidTlv,
633	                                               const ThreadLastTransactionTimeTlv *aLastTransactionTimeTlv,
634	                                               const Ip6::Address &                aDestination)
635	{
636	    otError          error;
637	    Coap::Message *  message;
638	    ThreadRloc16Tlv  rloc16Tlv;
639	    Ip6::MessageInfo messageInfo;
640	
641	    VerifyOrExit((message = Get<Coap::Coap>().NewMessage()) != NULL, error = OT_ERROR_NO_BUFS);
642	
643	    message->Init(OT_COAP_TYPE_CONFIRMABLE, OT_COAP_CODE_POST);
644	    SuccessOrExit(error = message->AppendUriPathOptions(OT_URI_PATH_ADDRESS_NOTIFY));
645	    SuccessOrExit(error = message->SetPayloadMarker());
646	
647	    SuccessOrExit(error = message->AppendTlv(aTargetTlv));
648	    SuccessOrExit(error = message->AppendTlv(aMlEidTlv));
649	
650	    rloc16Tlv.Init();
651	    rloc16Tlv.SetRloc16(Get<Mle::MleRouter>().GetRloc16());
652	    SuccessOrExit(error = message->AppendTlv(rloc16Tlv));
653	
654	    if (aLastTransactionTimeTlv != NULL)
655	    {
656	        SuccessOrExit(error = message->AppendTlv(*aLastTransactionTimeTlv));
657	    }
658	
659	    messageInfo.SetPeerAddr(aDestination);
660	    messageInfo.SetSockAddr(Get<Mle::MleRouter>().GetMeshLocal16());
661	    messageInfo.SetPeerPort(kCoapUdpPort);
662	
663	    SuccessOrExit(error = Get<Coap::Coap>().SendMessage(*message, messageInfo));
664	
665	    otLogInfoArp("Sending address notification for target %s", aTargetTlv.GetTarget().ToString().AsCString());
666	
667	exit:
668	
669	    if (error != OT_ERROR_NONE && message != NULL)
670	    {
671	        message->Free();
672	    }
673	}
674	
675	void AddressResolver::HandleTimer(Timer &aTimer)
676	{
677	    aTimer.GetOwner<AddressResolver>().HandleTimer();
678	}
679	
680	void AddressResolver::HandleTimer(void)
681	{
682	    bool continueTimer = false;
683	
684	    for (int i = 0; i < kCacheEntries; i++)
685	    {
686	        if (mCache[i].mState != Cache::kStateQuery)
687	        {
688	            continue;
689	        }
690	
691	        continueTimer = true;
692	
693	        if (mCache[i].mTimeout > 0)
694	        {
695	            mCache[i].mTimeout--;
696	
697	            if (mCache[i].mTimeout == 0)
698	            {
699	                mCache[i].mRetryTimeout =
700	                    static_cast<uint16_t>(kAddressQueryInitialRetryDelay * (1 << mCache[i].mFailures));
701	
702	                if (mCache[i].mRetryTimeout < kAddressQueryMaxRetryDelay)
703	                {
704	                    mCache[i].mFailures++;
705	                }
706	                else
707	                {
708	                    mCache[i].mRetryTimeout = kAddressQueryMaxRetryDelay;
709	                }
710	
711	                otLogInfoArp("Timed out waiting for address notification for %s, retry: %d",
712	                             mCache[i].mTarget.ToString().AsCString(), mCache[i].mRetryTimeout);
713	
714	                Get<MeshForwarder>().HandleResolved(mCache[i].mTarget, OT_ERROR_DROP);
715	            }
716	        }
717	        else if (mCache[i].mRetryTimeout > 0)
718	        {
719	            mCache[i].mRetryTimeout--;
720	        }
721	    }
722	
723	    if (continueTimer)
724	    {
725	        mTimer.Start(kStateUpdatePeriod);
726	    }
727	}
728	
729	void AddressResolver::HandleIcmpReceive(void *               aContext,
730	                                        otMessage *          aMessage,
731	                                        const otMessageInfo *aMessageInfo,
732	                                        const otIcmp6Header *aIcmpHeader)
733	{
734	    OT_UNUSED_VARIABLE(aMessageInfo);
735	
736	    static_cast<AddressResolver *>(aContext)->HandleIcmpReceive(*static_cast<Message *>(aMessage),
737	                                                                *static_cast<const Ip6::MessageInfo *>(aMessageInfo),
738	                                                                *static_cast<const Ip6::IcmpHeader *>(aIcmpHeader));
739	}
740	
741	void AddressResolver::HandleIcmpReceive(Message &               aMessage,
742	                                        const Ip6::MessageInfo &aMessageInfo,
743	                                        const Ip6::IcmpHeader & aIcmpHeader)
744	{
745	    OT_UNUSED_VARIABLE(aMessageInfo);
746	
747	    Ip6::Header ip6Header;
748	
749	    VerifyOrExit(aIcmpHeader.GetType() == Ip6::IcmpHeader::kTypeDstUnreach);
750	    VerifyOrExit(aIcmpHeader.GetCode() == Ip6::IcmpHeader::kCodeDstUnreachNoRoute);
751	    VerifyOrExit(aMessage.Read(aMessage.GetOffset(), sizeof(ip6Header), &ip6Header) == sizeof(ip6Header));
752	
753	    for (int i = 0; i < kCacheEntries; i++)
754	    {
755	        if (mCache[i].mState != Cache::kStateInvalid && mCache[i].mTarget == ip6Header.GetDestination())
756	        {
757	            InvalidateCacheEntry(mCache[i], kReasonReceivedIcmpDstUnreachNoRoute);
758	            break;
759	        }
760	    }
761	
762	exit:
763	    return;
764	}
